            <circle cx="65" cy="183" r="4" fill="#fff"/>
            <circle cx="135" cy="192" r="4" fill="#fff"/>
            <circle cx="205" cy="178" r="4" fill="#fff"/>
            <circle cx="275" cy="190" r="4" fill="#fff"/>
            <circle cx="345" cy="140" r="4" fill="#fff"/>
            <circle cx="415" cy="68" r="4" fill="#fff"/>
